exercises.solution:
estoque = {
    "tomate": [1000, 2.30],
    "alface": [500, 0.45],
    "batata": [2001, 1.20],
    "feijao": [100, 1.50]
}
total = 0.0

while True:
    produto = input("Digite o nome do produto (ou 'fim' para encerrar): ").strip().lower()
    if produto == "fim":
        break
    if produto in estoque:
        quantidade = int(input(f"Quantidade vendida de {produto}: "))
        if quantidade <= estoque[produto][0]:
            preco = estoque[produto][1]
            custo = preco * quantidade
            estoque[produto][0] -= quantidade
            total += custo
            print(f"{produto}: {quantidade} x R$ {preco:.2f} = R$ {custo:.2f}")
        else:
            print(f"Quantidade insuficiente em estoque! Saldo atual: {estoque[produto][0]}")
    else:
        print("Produto não encontrado no cadastro!")

print(f"\nCusto total das vendas: R$ {total:.2f}")

