exercises.solution:
frase = input("Digite uma frase: ")
contagem = {}

for letra in frase:
    if letra in contagem:
        contagem[letra] += 1
    else:
        contagem[letra] = 1

print(f"Dicionário de frequências: {contagem}")
for caractere, qtd in contagem.items():
    print(f"Caractere '{caractere}': {qtd} ocorrência(s)")

